  const obj = JSON.parse(line);
  if (obj.symbol === "web_element" || obj.symbol === "click" || obj.symbol === "select_option" || obj.symbol === "type_text" || obj.symbol === "press_key") {
    console.log(JSON.stringify(obj, null, 2));
  }
}
